// helper: track the pointer, let callers render from the coords
+function MouseTracker({ children }: {
+  children: (pos: { x: number; y: number }) => React.ReactNode;
+}) {
+  const [pos, setPos] = useState({ x: 0, y: 0 });
+  useEffect(() => {
+    const onMove = (e: PointerEvent) => setPos({ x: e.clientX, y: e.clientY });
+    window.addEventListener("pointermove", onMove);
+    return () => window.removeEventListener("pointermove", onMove);
+  }, []);
+  return <>{children(pos)}</>;
+}

// every call site looks like this — no library render loop involved:
+<MouseTracker>{({ x, y }) => <p>At {x}, {y}</p>}</MouseTracker>
+<MouseTracker>{({ x, y }) => <Crosshair x={x} y={y} />}</MouseTracker>
